def generator(rng):
    # Pick an odd n in a moderately large range to ensure nontrivial structure
    # and to avoid the even-n duplication at 1/2 which introduces multiplicities.
    # Also pick l so that the merge is nontrivial (not just the very first few terms).
    while True:
        n = rng.randrange(17, 101, 2)  # odd n in [17, 99]
        # total angles = 2n
        max_l = 2 * n - 2  # keep away from the full sum to avoid trivialities
        min_l = max(7, n // 3)  # ensure nontrivial merge
        if min_l >= max_l:
            continue
        # Bias l to be in the middle range often
        if rng.random() < 0.6:
            l = rng.randrange(min_l, min(max_l, (3 * n) // 2))
        else:
            l = rng.randrange(min_l, max_l)
        # Build the angle multiset for odd n: {j/n : 1<=j<=n-1} U {j/(n+2) : 1<=j<=n+1}
        angles = [Fraction(j, n) for j in range(1, n)] + [Fraction(j, n + 2) for j in range(1, n + 2)]
        # For odd n, these two sets are disjoint (gcd(n, n+2) = 1), total size 2n
        if len(angles) != 2 * n:
            continue
        angles.sort()
        # Ensure that among the first l there are contributions from both denominators to avoid triviality
        first_l = angles[:l]
        has_n = any(a.denominator == n for a in first_l)
        has_np2 = any(a.denominator == n + 2 for a in first_l)
        if not (has_n and has_np2):
            continue
        # Compute sum S and its m+n
        S = sum(first_l, Fraction(0, 1))
        p, q = S.numerator, S.denominator
        ans = p + q
        return {'n': n, 'l': l, 'answer': ans}

