def verifier(assign):
    # Validate presence of keys
    if 'n' not in assign or 'l' not in assign:
        # Missing parameters
        return (False, None)  # missing data
    n = assign['n']
    l = assign['l']
    # Domain checks: n odd, sufficiently large; l in a challenging range
    if not isinstance(n, int) or not isinstance(l, int):
        return (False, None)  # invalid types
    if n < 7 or n % 2 == 0:
        return (False, None)  # require odd n to avoid even-n multiplicity case
    total = 2 * n
    if not (5 <= l < total):
        return (False, None)  # l out of range
    # Build the angles as per the proven characterization for odd n
    angles = [Fraction(j, n) for j in range(1, n)] + [Fraction(j, n + 2) for j in range(1, n + 2)]
    # For odd n, the two sets are disjoint, size must be 2n
    if len(angles) != total:
        return (False, None)  # unexpected size; guard against mistakes
    angles.sort()
    # Optional difficulty guard: ensure first l contains both denominators
    first_l = angles[:l]
    has_n = any(a.denominator == n for a in first_l)
    has_np2 = any(a.denominator == n + 2 for a in first_l)
    if not (has_n and has_np2):
        return (False, None)  # too trivial instance; reject
    S = sum(first_l, Fraction(0, 1))
    p, q = S.numerator, S.denominator
    answer = p + q
    # If generator supplied an expected answer, check consistency; otherwise just return computed
    if 'answer' in assign:
        return (answer == assign['answer'], answer)
    return (True, answer)


        def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
            """Return dict with assignment/question/answer or raise RuntimeError."""
            start = time.time()
            attempts = 0
            while time.time() - start < timeout_seconds:
                attempts += 1
                rng = _RNGShim(seed + attempts)
                assignment = generator(rng)
                valid, answer = verifier(assignment)
                if valid:
                    question = LANGUAGE_WRAPPER.format(**assignment)
                    return {
                        "assignment": assignment,
                        "question": question,
                        "answer": answer,
                        "attempts": attempts,
                        "elapsed_seconds": time.time() - start,
                    }
            raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")
